import{_ as a,o as i,c as e,a2 as t}from"./chunks/framework.Ch4PdLd_.js";const c=JSON.parse('{"title":"项目指令（AGENTS.md）","description":"","frontmatter":{},"headers":[],"relativePath":"customize/context-files.md","filePath":"customize/context-files.md"}'),n={name:"customize/context-files.md"};function l(d,s,p,o,h,r){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="项目指令-agents-md" tabindex="-1">项目指令（AGENTS.md） <a class="header-anchor" href="#项目指令-agents-md" aria-label="Permalink to &quot;项目指令（AGENTS.md）&quot;">​</a></h1><p>项目指令（context file）是写给模型的长期说明：项目怎么构建、代码风格、哪些目录不要动、提交信息的格式等等。nek 会在每次请求时把它们交给模型。</p><p>这是最简单、最推荐的定制方式：不需要写代码，对 nek 的基础行为也没有副作用。</p><h2 id="文件名与查找规则" tabindex="-1">文件名与查找规则 <a class="header-anchor" href="#文件名与查找规则" aria-label="Permalink to &quot;文件名与查找规则&quot;">​</a></h2><p>nek 在每个目录里按以下优先级查找<strong>一个</strong>指令文件，找到第一个就停止：</p><ol><li><code>AGENTS.override.md</code></li><li><code>AGENTS.md</code></li><li><code>AGENTS.MD</code></li><li><code>CLAUDE.md</code></li><li><code>CLAUDE.MD</code></li></ol><p>查找的目录：</p><ol><li><strong>agent 目录</strong>（<code>~/.nek/agent/</code>）：对所有项目生效；</li><li><strong>工作目录及其所有上级目录</strong>，一直到文件系统根目录。</li></ol><p>加载顺序是：agent 目录的文件在最前，然后从最外层的上级目录一直到工作目录。所以越靠近工作目录的指令越靠后，也就越“具体”。</p><p>例如在 <code>~/work/shop/api</code> 里启动 nek：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.nek/agent/AGENTS.md      ← 1. 个人通用习惯</span></span>
<span class="line"><span>~/work/AGENTS.md            ← 2. 工作区约定</span></span>
<span class="line"><span>~/work/shop/AGENTS.md       ← 3. 仓库约定</span></span>
<span class="line"><span>~/work/shop/api/AGENTS.md   ← 4. api 子项目的约定</span></span></code></pre></div><p>四个文件都会加载。</p><h3 id="agents-override-md" tabindex="-1">AGENTS.override.md <a class="header-anchor" href="#agents-override-md" aria-label="Permalink to &quot;AGENTS.override.md&quot;">​</a></h3><p><code>AGENTS.override.md</code> 只在<strong>同一个目录里</strong>替代 <code>AGENTS.md</code> / <code>CLAUDE.md</code>，不影响 agent 目录或其他目录的指令文件。适合在不改动团队共享的 <code>AGENTS.md</code> 的前提下，放一份个人版本（记得把它加进 <code>.gitignore</code>）。</p><p>nekcode 仓库的 <code>AGENTS.md</code> 只包含通用开发说明；本仓库已忽略 <code>AGENTS.override.md</code> 和 <code>.nek/</code>。全局个人指令放在 <code>~/.nek/agent/AGENTS.md</code>，不要把个人指令复制到公开仓库的默认文件里。</p><h3 id="git-worktree" tabindex="-1">git worktree <a class="header-anchor" href="#git-worktree" aria-label="Permalink to &quot;git worktree&quot;">​</a></h3><p>在嵌套于主仓库内的 git worktree 中工作时，worktree 自己的指令文件会屏蔽主仓库根目录的同名文件，避免同一份仓库指令被加载两次。</p><h2 id="指令如何发给模型" tabindex="-1">指令如何发给模型 <a class="header-anchor" href="#指令如何发给模型" aria-label="Permalink to &quot;指令如何发给模型&quot;">​</a></h2><p>指令文件<strong>不</strong>放在系统提示词里。每次请求时，nek 在开头的系统消息之后插入一条单独的消息，内容大致是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;project_instructions&gt;</span></span>
<span class="line"><span>（各指令文件的内容，按上面的顺序，每个文件标注路径）</span></span>
<span class="line"><span>&lt;/project_instructions&gt;</span></span></code></pre></div><p>这条消息不写入对话记录。这样在一个会话里，系统提示词和工具声明保持不变，服务商的提示词缓存不会因为你修改了指令而整段失效。</p><p>后面的指令优先于前面的指令；你在对话中的最新要求优先于所有指令文件。</p><h2 id="信任与安全" tabindex="-1">信任与安全 <a class="header-anchor" href="#信任与安全" aria-label="Permalink to &quot;信任与安全&quot;">​</a></h2><p>指令文件的加载<strong>不需要</strong>项目信任。也就是说，在一个不受信任的仓库里启动 nek，那个仓库的 <code>AGENTS.md</code> 仍然会被加载。请把陌生仓库里的指令当作不可信输入，见 <a href="/nekcode/guide/security">安全使用</a>。</p><p>不想加载任何指令文件时：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">nek</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-context-files</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # 或 -nc</span></span></code></pre></div><h2 id="修改后生效" tabindex="-1">修改后生效 <a class="header-anchor" href="#修改后生效" aria-label="Permalink to &quot;修改后生效&quot;">​</a></h2><p>会话进行中修改了指令文件，运行 <code>/reload</code>。启动信息（按 <code>Ctrl+O</code> 展开）会列出当前加载了哪些指令文件。</p><h2 id="写好指令的建议" tabindex="-1">写好指令的建议 <a class="header-anchor" href="#写好指令的建议" aria-label="Permalink to &quot;写好指令的建议&quot;">​</a></h2><ul><li>写<strong>具体、可验证</strong>的规则：“提交前运行 <code>npm run check</code>”比“保证代码质量”有用。</li><li>写清楚项目的命令：怎么安装依赖、构建、跑测试、跑单个测试。</li><li>写下不能做的事：不能改的目录、不能提交的文件、禁止的命令。</li><li>保持简短。指令每次请求都会发送，冗长的指令会占用上下文。</li><li>大段的专项知识（某个子系统的设计、某类任务的步骤）更适合做成 <a href="/nekcode/customize/skills">Skill</a>，按需加载。</li></ul><p>示例：</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># 项目约定</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 命令</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 安装依赖：</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`pnpm install\`</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 检查：</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`pnpm check\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">（改完代码后必须运行，修复所有错误）</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 单个测试：</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`pnpm vitest run path/to/file.test.ts\`</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 代码</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> TypeScript 严格模式，不要使用 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`any\`</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 新的 API 路由放在 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`src/routes/\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">，每个路由一个文件</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## 禁止</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 不要修改 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`src/generated/\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">，它由 </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`pnpm codegen\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 生成</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 未经要求不要提交（git commit）</span></span></code></pre></div><h2 id="其他改变系统提示词的方式" tabindex="-1">其他改变系统提示词的方式 <a class="header-anchor" href="#其他改变系统提示词的方式" aria-label="Permalink to &quot;其他改变系统提示词的方式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式</th><th>作用</th></tr></thead><tbody><tr><td><code>~/.nek/agent/APPEND_SYSTEM.md</code>、<code>.nek/APPEND_SYSTEM.md</code></td><td>在系统提示词末尾追加</td></tr><tr><td><code>~/.nek/agent/SYSTEM.md</code>、<code>.nek/SYSTEM.md</code></td><td>替换整个默认系统提示词（身份句保留）</td></tr><tr><td><code>--append-system-prompt &lt;文本或文件&gt;</code></td><td>本次运行追加</td></tr><tr><td><code>--system-prompt &lt;文本或文件&gt;</code></td><td>本次运行替换</td></tr></tbody></table><p>替换系统提示词会丢掉 nek 默认的工具使用说明和工作方式约定，一般不建议。</p>`,35)])])}const g=a(n,[["render",l]]);export{c as __pageData,g as default};
